import pandas as pd
from itertools import combinations

def cost_analysis(toppings: pd.DataFrame) -> pd.DataFrame:
    df = toppings.sort_values(by='topping_name').reset_index(drop=True)
    rows = []
    for c1, c2, c3 in combinations(df.itertuples(), 3):
        pizza = f"{c1.topping_name},{c2.topping_name},{c3.topping_name}"
        total_cost = round(float(c1.cost) + float(c2.cost) + float(c3.cost), 2)
        rows.append({'pizza': pizza, 'total_cost': total_cost})
    res = pd.DataFrame(rows)
    if res.empty:
        return pd.DataFrame(columns=['pizza', 'total_cost'])
    return res.sort_values(by=['total_cost', 'pizza'], ascending=[False, True])
